import sys
from events.importer import import_bytes, ImportProblem
from events.store import Store

if __name__ == '__main__':
    try:
        print(import_bytes(sys.stdin.buffer.read(), Store()))
    except ImportProblem as error:
        print(f'line {error.line}', file=sys.stderr)
        raise SystemExit(1)
